#!/usr/bin/env python3
"""Build new full-axis overlay only after independent literal2010 source admission.
Existing four-region values/qualities are preserved. No model predictions are used.
"""
from pathlib import Path
import argparse,json,hashlib,datetime
import pandas as pd,numpy as np
B=Path(__file__).resolve().parent;ROOT=B.parent
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def equal(a,b):
 a=pd.Series(a).reset_index(drop=True);b=pd.Series(b).reset_index(drop=True)
 return ((a==b)|(a.isna()&b.isna())).fillna(False).all()
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--source-admission',type=Path,required=True);ap.add_argument('--output',type=Path,required=True);args=ap.parse_args();out=args.output.resolve();assert not out.exists(),'Immutable new output directory required'
 source=B/'national_table5_all_new_primary2010_numeric_candidates.parquet';axis=ROOT/'data/source_controls_cycle05/full_settlement_axis_cycle05_federal_children.parquet';prior=ROOT/'demography2010_recovery/root_reviewed_primary2010_four_regions_v1.parquet';prioradm=ROOT/'demography2010_recovery/root_four_regions_admission_receipt.json';freeze=B/'national_table5_source_freeze_manifest.json';admission=args.source_admission.resolve();ac=json.loads(admission.read_text());assert ac.get('all_checks_passed')is True and ac.get('accepted_new_numeric_candidates_sha256')==sha(source),'Independent exact source candidate admission required';statuses=ac['accepted_identity_statuses'];assert statuses
 pins={str(p):sha(p)for p in [source,axis,prior,prioradm,freeze,admission,Path(__file__)]};bound=json.loads(freeze.read_text())['files_sha256']
 for p,h in bound.items():assert sha(Path(p))==h,'Frozen source changed: '+p
 a=pd.read_parquet(axis);old=pd.read_parquet(prior).set_index('id');new=pd.read_parquet(source).set_index('strict_uid');assert a.id.is_unique and len(a)==173862 and old.index.is_unique and new.index.is_unique;assert set(old.index)<=set(a.id)and set(new.index)<=set(a.id);assert not set(old.index)&set(new.index);assert new.link_status.isin(statuses).all()and new.eligible_numeric_recovery.all()and new.population2010_primary_numeric_cell.notna().all()and new.population2010_primary_numeric_cell.ge(0).all();assert old.reviewed_primary2010_override_allowed.eq(True).all()
 f=a[['id','region','name','type','source_record_id_2010','population_2010','population_value_quality_2010']].copy().set_index('id');f['original_axis_population2010']=f.population_2010;f['original_axis_quality2010']=f.population_value_quality_2010.astype('string');f['original_axis_sourceUID2010']=f.source_record_id_2010.astype('string');f['prior_effective_population2010']=f.population_2010;f['prior_effective_quality2010']=f.population_value_quality_2010.astype('string');f['prior_effective_sourceUID2010']=f.source_record_id_2010.astype('string');f['prior_accepted_four_region_overlay_applied']=f.index.isin(old.index)
 f.loc[old.index,'prior_effective_population2010']=old.reviewed_primary2010_population;f.loc[old.index,'prior_effective_quality2010']=old.reviewed_primary2010_quality.astype('string');f.loc[old.index,'prior_effective_sourceUID2010']=old.source_record_id.astype('string')
 f['reviewed_primary2010_population']=f.prior_effective_population2010;f['reviewed_primary2010_quality']=f.prior_effective_quality2010;f['reviewed_primary2010_sourceUID']=f.prior_effective_sourceUID2010;f['reviewed_primary2010_override_allowed']=f.index.isin(old.index)|f.index.isin(new.index);f['actual_override_applied']=f.index.isin(new.index);f['primary2010_new_primary_recovery_applied']=f.actual_override_applied;f['source_primary2010_admission_sha256']=pd.Series(pd.NA,index=f.index,dtype='string');f.loc[old.index,'source_primary2010_admission_sha256']=sha(prioradm)
 assert f.loc[new.index,'prior_effective_quality2010'].eq('secondary_confidentiality_protected_value_exact_scope_unverified').all(),'Do not overwrite another admitted primary source'
 f.loc[new.index,'reviewed_primary2010_population']=new.population2010_primary_numeric_cell;f.loc[new.index,'reviewed_primary2010_quality']='reviewed_primary_reported_value';f.loc[new.index,'reviewed_primary2010_sourceUID']=new.source_row_id.astype('string').map(lambda x:'ROSSTAT2010:'+x);f.loc[new.index,'source_primary2010_admission_sha256']=sha(admission)
 f['changed_population']=~((f.reviewed_primary2010_population==f.prior_effective_population2010)|(f.reviewed_primary2010_population.isna()&f.prior_effective_population2010.isna()));f['changed_quality']=~((f.reviewed_primary2010_quality==f.prior_effective_quality2010)|(f.reviewed_primary2010_quality.isna()&f.prior_effective_quality2010.isna()));f['changed_sourceUID']=~((f.reviewed_primary2010_sourceUID==f.prior_effective_sourceUID2010)|(f.reviewed_primary2010_sourceUID.isna()&f.prior_effective_sourceUID2010.isna()))
 for field in ['source_pdf_sha256','source_pdf_url','source_label_raw','source_row_id','source_native2010_parent_raw','source_total_cell_raw','source_male_cell_raw','source_female_cell_raw','source_statistical_population_section_explicit']:
  f['new_primary2010_'+field]=f.index.map(new[field]).astype('string')
 for field in ['source_pdf_page','source_layout_line']:f['new_primary2010_'+field]=pd.Series(f.index.map(new[field]),index=f.index,dtype='Int64')
 f['new_primary2010_link_status']=f.index.map(new.link_status).astype('string');f['source_2010_boundary_equals2021_boundary_assumed']=False;f['population_identity_link_uses_count_agreement']=False;f['new_dash_derived_zero_admitted']=False
 assert equal(f.loc[old.index,'reviewed_primary2010_population'],old.reviewed_primary2010_population)and equal(f.loc[old.index,'reviewed_primary2010_quality'],old.reviewed_primary2010_quality);assert not f.loc[~f.actual_override_applied,['changed_population','changed_quality','changed_sourceUID']].fillna(False).any().any();assert f.actual_override_applied.sum()==len(new);assert f.reviewed_primary2010_override_allowed.sum()==len(old)+len(new)
 out.mkdir(parents=True);f.reset_index().to_parquet(out/'full_axis_primary2010_overlay.parquet',index=False);f[f.actual_override_applied].reset_index().to_parquet(out/'all_new_primary2010_applied_changes.parquet',index=False)
 for p,h in pins.items():assert sha(Path(p))==h
 receipt={'status':'BUILT_FROM_INDEPENDENTLY_ADMITTED_PRIMARY2010_SOURCE_PENDING_FINAL_OVERLAY_SHA_READBACK','created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source_sha256':pins,'full_axis_records':len(f),'prior_accepted_four_region_records_preserved':len(old),'new_primary2010_recoveries':len(new),'new_changed_population':int(f.changed_population.sum()),'new_changed_quality':int(f.changed_quality.sum()),'new_same_numeric_value_quality_only':int((f.actual_override_applied&~f.changed_population).sum()),'cumulative_override_allowed':int(f.reviewed_primary2010_override_allowed.sum()),'zero_prior_primary_conflicts':True,'source_admission_sha256':sha(admission),'source_controls':'All source candidates independently admitted; exact raw source cells and old/new values/quality/sourceUID retained. Existingprimary readbacks never doubled. No newdash zeros.','flag_semantics':{'actual_override_applied':'New table5 source changes relative to prior effective axis including existing acceptedfourregions','reviewed_primary2010_override_allowed':'Cumulative override vs originalrawaxis; oldacceptedfourregions OR newindependentlyadmittedrows','changed_population':'Finalnumeric differs from prior_effective_population2010; bothmissing isunchanged','changed_quality':'Finalsourcequality differs from prior_effective_quality2010, including same-number newprimaryproof','primary2010_new_primary_recovery_applied':'Use to aggregate newprimary membercounts/shares; doesnotcount existingfourregions again'},'no_old_axis_or_model_mutation':True,'no_classification_or_weight_tuning':True,'outputs_sha256':{p.name:sha(p)for p in out.iterdir()if p.is_file()}}
 (out/'overlay_receipt.json').write_text(json.dumps(receipt,ensure_ascii=False,indent=2,allow_nan=False));(out/'freeze_manifest.json').write_text(json.dumps({'status':'NEW_FULLAXIS_PRIMARY2010_OVERLAY_FROZEN_PENDING_INDEPENDENT_FINAL_READBACK','accepted_source_admission_sha256':sha(admission),'files_sha256':{p.name:sha(p)for p in out.iterdir()if p.is_file()}},indent=2));print(json.dumps({k:receipt[k]for k in ['full_axis_records','new_primary2010_recoveries','new_changed_population','new_changed_quality','new_same_numeric_value_quality_only','cumulative_override_allowed']},ensure_ascii=False))
if __name__=='__main__':main()
